const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const products=['显示屏','风速仪','控制器','扶手箱','电源模块','二合一模块','摄像头'];
const depts=['智能化研究院','电动化研究院','系统一所','系统二所','工艺部','生产部','项目部','质量部','储运部'];
