const states=['待处理','处理中','待验证','已闭环'];
const TODAY='2026-10-17', STORE='quality-insight-records-v1';
const iso=d=>d.toISOString().slice(0,10), money=n=>'¥'+Math.round(n).toLocaleString('zh-CN'), sum=(a,k)=>a.reduce((t,r)=>t+(typeof k==='function'?k(r):r[k]),0);
function seed(){return Array.from({length:168},(_,i)=>{const p=products[(i*11+Math.floor(i/7))%7],d=depts[i%8],other=depts[(i+3)%8],date=new Date(Date.UTC(i<144?2026:2025,0,6));date.setUTCDate(date.getUTCDate()+(i*13)%280);const dt=iso(date),deadline=iso(new Date(+date+(7+i%5*5)*86400000)),amount=1600+(i*7919)%68000;return{id:'CQ-'+dt.slice(0,4)+'-'+String(i+1).padStart(4,'0'),date:dt,product:p,model:p+' '+['A01','B02','C03'][i%3],issue:issues[(i+Math.floor(i/8))%6],customer:['华东客户','华南客户','华北客户','西南客户'][i%4],amount,waiver:Math.round(amount*(.08+i%6*.045)),dept:d,shares:[{dept:d,ratio:60+i%4*10},{dept:other,ratio:40-i%4*10}].filter(s=>s.ratio),deadline,status:i%7<4?'已闭环':states[i%3],note:'已受理客户反馈，正在进行问题定位与原因分析。',history:[{date:dt+' 09:30',text:'客诉登记，完成初步判责。'}]}})}
let records;try{records=JSON.parse(localStorage.getItem(STORE))||seed()}catch{records=seed()}
const categories=['客户抱怨','正式投诉'];
function migrateRecord(r,i){
 const old=r.category||['客户抱怨','质量投诉','批量问题'][i%6<3?0:i%6<5?1:2];
 return {...r,category:old==='客户抱怨'?'客户抱怨':'正式投诉',isBatch:old==='客户抱怨'?false:old==='批量问题'||r.isBatch===true};
}
records=records.map(migrateRecord);
try{localStorage.setItem(STORE,JSON.stringify(records))}catch{/* Browsing remains available if storage is disabled. */}
let period='年度',rankMode='投诉数量',repeatMode='同一产品',page=1,active=null,extraFilter=null;
let customRange={start:'2026-01-01',end:TODAY},trendBuckets=[];
$('#product').innerHTML='<option value="">全部产品</option>'+products.map(p=>`<option>${p}</option>`).join('');
$('#department').innerHTML='<option value="">全部责任部门</option>'+depts.map(p=>`<option>${p}</option>`).join('');
function weekInfo(s){let d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));let y=d.getUTCFullYear(),start=new Date(Date.UTC(y,0,1));return{year:y,week:Math.ceil(((d-start)/86400000+1)/7)}}
