function weekRange(y,w){let s=weekStart(y,w);return s.slice(5)+' — '+addDays(s,6).slice(5)}
function intervalOptions(){
 const el=$('#interval'),custom=period==='自定义日期';el.hidden=period==='年度'||custom;$('#year').hidden=custom;$('#customDates').hidden=!custom;
 let opts=[];if(period==='季度')opts=Array.from({length:4},(_,i)=>[i+1,'Q'+(i+1)+' · 第'+(i+1)+'季度']);
 if(period==='月度')opts=Array.from({length:12},(_,i)=>[i+1,(i+1)+'月']);
 if(period==='周度'){let y=+$('#year').value,n=weekInfo(y+'-12-28').week;opts=Array.from({length:n},(_,i)=>[i+1,'W'+String(i+1).padStart(2,'0')+' · '+weekRange(y,i+1)])}
 el.innerHTML=opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');
 if(period==='季度')el.value='4';if(period==='月度')el.value='10';if(period==='周度')el.value=String(weekInfo(TODAY).week);
 if(custom){$('#dateStart').value=customRange.start;$('#dateEnd').value=customRange.end;$('#dateError').textContent=''}
}
function dateRange(){let y=+$('#year').value,n=+$('#interval').value;
 if(period==='自定义日期')return {...customRange};
 if(period==='周度'){let start=weekStart(y,n);return{start,end:addDays(start,6)}}
 let m=period==='季度'?(n-1)*3:period==='月度'?n-1:0,months=period==='季度'?3:period==='月度'?1:12;
 return {start:iso(new Date(Date.UTC(y,m,1))),end:iso(new Date(Date.UTC(y,m+months,0)))};
}
function selected(){let {start,end}=dateRange();return records.filter(r=>r.date>=start&&r.date<=end&&(!$('#product').value||r.product===$('#product').value)&&(!$('#department').value||r.shares.some(s=>s.dept===$('#department').value)))}
function overdue(r){return r.status!=='已闭环'&&r.deadline<TODAY}
function badge(r){let cls=r.status==='已闭环'?'closed':r.status==='待验证'?'verify':r.status==='待处理'?'pending':'';return `<span class="badge ${cls}">${r.status}</span>${overdue(r)?' <span class="badge overdue">超期</span>':''}`}
