function matchesDrill(r,f=extraFilter){return !f||(!f.category||r.category===f.category)&&(!f.batch||r.isBatch)&&(!f.model||r.model===f.model)&&(!f.product||r.product===f.product)&&(!f.issue||r.issue===f.issue)&&(!f.responsibleDept||r.shares.some(s=>s.dept===f.responsibleDept))&&(!f.mainDept||r.dept===f.mainDept)&&(!f.open||r.status!=='已闭环')&&(!f.state||r.status===f.state)&&(!f.late||overdue(r))&&(!f.within||!overdue(r))&&(!f.start||r.date>=f.start)&&(!f.end||r.date<=f.end)}
