function exportRecords(){let data=exportData(),url=URL.createObjectURL(new Blob([csvText(data)],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download='客诉明细-'+dateRange().start+'-'+dateRange().end+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前筛选范围 '+(data.length-1)+' 条明细')}

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openDetail(id){active=id;const r=records.find(r=>r.id===id);$('#detail').innerHTML=`<div class="detail-summary"><span class="tiny">${r.id}</span><h3>${r.model} · ${r.issue}</h3>${badge(r)}<div class="detail-grid"><div><small>客户 / 分类</small><strong>${r.customer} / ${r.category}${r.isBatch?" · 批量问题":""}</strong></div><div><small>填表日期</small><strong>${r.date}</strong></div><div><small>投诉金额</small><strong>${money(r.amount)}</strong></div><div><small>减免 / 实际赔付</small><strong>${money(r.waiver)} / ${money(r.amount-r.waiver)}</strong></div></div><h4>责任分摊</h4>${r.shares.map(s=>`<div class="responsibility"><span>${s.dept}${s.dept===r.dept?' · 主责':''}</span><span>${s.ratio}% · ${money(r.amount*s.ratio/100)}</span></div>`).join('')}<h4>更新处理进度</h4><label for="editStatus">处理状态</label><select id="editStatus">${states.map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select><label for="editDeadline">截止日期</label><input id="editDeadline" type="date" value="${r.deadline}" min="${r.date}"><label for="editNote">处理措施 / 最新进展</label><textarea id="editNote" maxlength="2000">${esc(r.note)}</textarea><p class="help">流程：待处理 → 处理中 → 待验证 → 已闭环。演示身份为质量管理员，可验证闭环；保存后仅保留在当前浏览器。正式权限审批需连接后台。</p><button id="save" class="primary">保存处理进度</button><h4>处理记录</h4><div class="timeline">${r.history.slice().reverse().map(h=>`<p>${esc(h.text)}<small>${esc(h.date)}</small></p>`).join('')}</div></div>`;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#close').focus();$('#save').onclick=saveDetail}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function saveDetail(){let r=records.find(r=>r.id===active),status=$('#editStatus').value,note=$('#editNote').value.trim(),deadline=$('#editDeadline').value;if(!deadline||deadline<r.date){toast('截止日期不能早于填表日期');return}if(!note){toast('请填写处理措施或最新进展');return}if(states.indexOf(status)>states.indexOf(r.status)+1){toast('请依次完成处理并提交验证');return}if(r.status==='已闭环'&&status!=='已闭环'){toast('已闭环记录不可直接重开');return}let updated={...r,status,note,deadline,history:[...r.history,{date:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),text:`质量管理员：${r.status} → ${status}；截止 ${deadline}；${note}`} ]};let next=records.map(x=>x.id===active?updated:x);try{localStorage.setItem(STORE,JSON.stringify(next))}catch{toast('保存失败：浏览器存储不可用或空间不足');return}records=next;render();openDetail(active);toast('处理进度已保存到当前浏览器')}
function close(){ $('#overlay').hidden=true;document.body.style.overflow='';$(`[data-id="${active}"]`)?.focus() }$('#close').onclick=close;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close()};document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')close();if(e.key==='Tab'){let els=[...$('.drawer').querySelectorAll('button,input,textarea,select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function applyCustomDates(){const start=$('#dateStart').value,end=$('#dateEnd').value;let error=!start||!end?'请选择开始日期和结束日期':start>end?'结束日期不能早于开始日期':'';$('#dateError').textContent=error;if(error)return false;customRange={start,end};page=1;extraFilter=null;render();return true}
$('#period').onclick=e=>{if(e.target.tagName!=='BUTTON')return;period=e.target.textContent;$$('#period button').forEach(b=>b.classList.toggle('selected',b===e.target));intervalOptions();page=1;extraFilter=null;render()};
$('#applyDates').onclick=applyCustomDates;
['year','interval','product','department'].forEach(id=>$('#'+id).onchange=()=>{if(id==='year')intervalOptions();page=1;extraFilter=null;render()});
$('#clearDrill').onclick=()=>{extraFilter=null;page=1;renderRows()};
$('#listExport').onclick=exportRecords;
$('#rankMode').onclick=e=>{if(e.target.tagName!=='BUTTON')return;rankMode=e.target.textContent;$$('#rankMode button').forEach(b=>b.classList.toggle('selected',b===e.target));renderRanks(selected())};$('#repeatMode').onclick=e=>{if(e.target.tagName!=='BUTTON')return;repeatMode=e.target.textContent;$$('#repeatMode button').forEach(b=>b.classList.toggle('selected',b===e.target));renderRepeats(selected())};$('#deptMode').onchange=()=>renderRanks(selected());
$('#reset').onclick=()=>{$('#year').value='2026';$('#product').value='';$('#department').value='';$('#status').value='全部状态';$('#search').value='';extraFilter=null;page=1;period='年度';$$('#period button').forEach(b=>b.classList.toggle('selected',b.textContent===period));intervalOptions();render()};$('#search').oninput=()=>{page=1;renderRows()};$('#status').onchange=()=>{page=1;renderRows()};$('#prev').onclick=()=>{page--;renderRows()};$('#next').onclick=()=>{page++;renderRows()};
$$('nav button').forEach(e=>e.onclick=()=>{$$('nav button').forEach(b=>b.classList.toggle('active',b===e));$('.crumb').innerHTML='质量管理 <span>/</span> '+e.querySelector('span').textContent;let dest=e.dataset.nav==='overview'?'.page':'#'+e.dataset.nav;$(dest).scrollIntoView()});
$('#export').onclick=exportRecords;
for(const el of [$('#ranking'),$('#deptRanking')]){let paused=false;el.onmouseenter=()=>paused=true;el.onmouseleave=()=>paused=false;el.onfocusin=()=>paused=true;el.onfocusout=()=>paused=false;setInterval(()=>{if(paused||document.hidden||!$('#overlay').hidden||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;let end=el.scrollHeight-el.clientHeight;if(end>0)el.scrollTo({top:el.scrollTop>=end-2?0:Math.min(end,el.scrollTop+84),behavior:'smooth'})},4500)}
intervalOptions();render();
